@@preprocessing
<%
// ═══════════════════════════════════════════════════════════════════
// 东渊西曜 动态内容控制器 v4.0
// 功能：根据游戏状态动态加载对应协议条目
// ═══════════════════════════════════════════════════════════════════

// ========== 获取基础变量 ==========
if (typeof currentContinent === 'undefined') var currentContinent = getvar('stat_data.玩家.本体.当前大陆') || '';
if (typeof currentCity === 'undefined') var currentCity = getvar('stat_data.玩家.本体.当前城市') || '';
if (typeof currentCityUID === 'undefined') var currentCityUID = getvar('stat_data.玩家.本体.当前城市UID') || '';
if (typeof currentLocation === 'undefined') var currentLocation = getvar('stat_data.玩家.本体.当前位置') || '';
if (typeof playerRealm === 'undefined') var playerRealm = getvar('stat_data.玩家.本体.实力境界') || '凡人';
if (typeof playerSystem === 'undefined') var playerSystem = getvar('stat_data.玩家.本体.实力体系') || '';

// ========== 获取状态变量 ==========
if (typeof isInBattle === 'undefined') var isInBattle = getvar('stat_data.当前战斗.是否战斗中') || false;
if (typeof isInDungeon === 'undefined') var isInDungeon = getvar('stat_data.当前副本.是否在副本中') || false;
if (typeof playerStatus === 'undefined') var playerStatus = getvar('stat_data.玩家.本体.当前状态') || '正常';
if (typeof travelStatus === 'undefined') var travelStatus = getvar('stat_data.旅行状态.移动状态') || '静止';
if (typeof isTraveling === 'undefined') var isTraveling = travelStatus !== '静止';

// ========== 获取用户最新消息 ==========
if (typeof messageText === 'undefined') {
  const userMessages = TavernHelper.getChatMessages('-1', { role: 'user' });
  var messageText = userMessages.length > 0 ? userMessages[0].message : '';
}

// ========== 判断是否第0轮（开局） ==========
const currentFloorMessages = TavernHelper.getChatMessages(-1);
const isFloorZero = currentFloorMessages.length > 0 && currentFloorMessages[0].message_id === 0;
%>

<%# ═══════════════════════════════════════════════════════════════════ %>
<%# 核心规则（始终加载）                                                 %>
<%# ═══════════════════════════════════════════════════════════════════ %>
<%- await getwi(null, '[mvu_plot]核心规则') %>

<% if (!isFloorZero) { %>

<%# ═══════════════════════════════════════════════════════════════════ %>
<%# 状态驱动的协议加载                                                   %>
<%# ═══════════════════════════════════════════════════════════════════ %>

<%# 战斗状态 → 加载战斗协议 %>
<% if (isInBattle) { %>
  <%- await getwi(null, '[mvu_plot]战斗协议') %>
<% } %>

<%# 副本状态 → 加载传送门协议 %>
<% if (isInDungeon) { %>
  <%- await getwi(null, '[mvu_plot]传送门协议') %>
<% } %>

<%# 旅行状态 → 加载旅行协议 %>
<% if (isTraveling) { %>
  <%- await getwi(null, '[mvu_plot]旅行协议') %>
<% } %>

<%# ═══════════════════════════════════════════════════════════════════ %>
<%# 关键词驱动的协议加载                                                 %>
<%# ═══════════════════════════════════════════════════════════════════ %>

<%# 修炼相关关键词 %>
<% if (messageText.includes('修炼') || messageText.includes('打坐') || messageText.includes('突破') || messageText.includes('炼气') || messageText.includes('筑基') || playerStatus.includes('修炼')) { %>
  <%- await getwi(null, '[mvu_plot]修炼协议') %>
<% } %>

<%# 任务相关关键词 %>
<% if (messageText.includes('任务') || messageText.includes('委托') || messageText.includes('悬赏') || messageText.includes('接取')) { %>
  <%- await getwi(null, '[mvu_plot]任务协议') %>
<% } %>

<%# 传送门相关关键词 %>
<% if (messageText.includes('传送门') || messageText.includes('魔物') || messageText.includes('异界') || messageText.includes('副本')) { %>
  <%- await getwi(null, '[mvu_plot]传送门协议') %>
<% } %>

<%# 势力相关关键词 %>
<% if (messageText.includes('宗门') || messageText.includes('势力') || messageText.includes('声望') || messageText.includes('加入')) { %>
  <%- await getwi(null, '[mvu_plot]势力交互协议') %>
<% } %>

<% } else { %>
<%# ═══════════════════════════════════════════════════════════════════ %>
<%# 第0轮（开局）→ 加载创世协议                                          %>
<%# ═══════════════════════════════════════════════════════════════════ %>
  <%- await getwi(null, '[mvu_plot]创世协议') %>
<% } %>
